'use strict';

/**
* WebAssembly memory page size (in bytes).
*
* @module @stdlib/constants/wasm/page-size
* @type {number}
*
* @example
* var PAGE_SIZE = require( '@stdlib/constants/wasm/page-size' );
* // returns 65536
*/

// MAIN //

/**
* WebAssembly memory page size (in bytes).
*
* @constant
* @type {number}
*/
var PAGE_SIZE = 64 * 1024; // 65536 bytes


// EXPORTS //

module.exports = PAGE_SIZE;
